def fact(n):
    return 1 if n <= 1 else n * fact(n - 1)
print(fact(5))

def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)
print(fib(7))

def s(n):
    if n == 0:
        return 0
    return n + s(n - 1)
print(s(4))

